# find closure: pair (a,b) both contacted w (or interacted with w) at times ta,tb; then a-b interact within 800 of max(ta,tb)
# build adjacency events undirected
adj=collections.defaultdict(list)
for u,v,t in events:
    adj[u].append((v,t)); adj[v].append((u,t))
pairev=collections.defaultdict(list)
for u,v,t in events:
    pairev[frozenset((u,v))].append(t)
closures=[]
for u,v,t in win:  # closing edge candidate
    a,b=u,v
    # find common neighbor w with edges to a and b before t, latest support time
    best=None
    for w,ta in adj[a]:
        if w==b or ta>=t: continue
        for w2,tb in adj[b]:
            if w2!=w or tb>=t: continue
            supp=max(ta,tb)
            lag=t-supp
            if lag<=800:
