def count_closures(ev,adjd,lo,hi,lagmax=800):
    c=0
    for u,v,t in ev:
        if not (lo<=t<=hi): continue
        na={};nb={}
        for w,ta in adjd[u]:
            if ta<t and w!=v: na[w]=max(na.get(w,-1),ta)
        for w,tb in adjd[v]:
            if tb<t and w!=u: nb[w]=max(nb.get(w,-1),tb)
        for w in na:
            if w in nb and t-max(na[w],nb[w])<=lagmax:
                c+=1; break
    return c
